// This file defines the structure of our data models

/**
 * Utility function to generate UUID
 */
export function generateId() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = (Math.random() * 16) | 0
    const v = c === 'x' ? r : (r & 0x3) | 0x8
    return v.toString(16)
  })
}

/**
 * Date utility functions
 */
export const DateUtils = {
  toISOString: date => (date instanceof Date ? date.toISOString() : new Date(date).toISOString()),
  addDays: (date, days) => {
    const result = new Date(date)
    result.setDate(result.getDate() + days)
    return result
  },
  diffInDays: (date1, date2) => {
    const oneDay = 24 * 60 * 60 * 1000
    return Math.round((new Date(date2) - new Date(date1)) / oneDay)
  },
  isWeekend: date => {
    const day = new Date(date).getDay()
    return day === 0 || day === 6 // Sunday or Saturday
  },
  getWorkingDays: (startDate, endDate, excludeWeekends = true) => {
    let count = 0
    const start = new Date(startDate)
    const end = new Date(endDate)

    while (start <= end) {
      if (!excludeWeekends || !DateUtils.isWeekend(start)) {
        count++
      }
      start.setDate(start.getDate() + 1)
    }
    return count
  }
}

