/**
 * Create a new task object with default values
 */
export function createTask(taskData = {}) {
  return {
    id: generateId(),
    title: '',
    description: '',
    status: TaskStatus.TODO,
    priority: TaskPriority.MEDIUM,
    startDate: '',
    endDate: '',
    estimatedTime: '',
    actualTime: null,
    dependencies: [], // Array of dependency objects: {fromTaskId, type, lag}
    subtasks: [], // Array of subtask IDs (maintained for backward compatibility)
    parentTask: null, // ID of parent task (for subtask relationships)
    // Enhanced hierarchy support
    level: 0, // Depth level in hierarchy (0 = root task, 1 = first level subtask, etc.)
    hierarchyPath: [], // Array of parent IDs from root to current task (excluding self)
    order: 0, // Order within the same parent/level for sorting
    isExpanded: true, // Whether subtasks are visible in UI
    // Progress tracking
    progressWeight: 1, // Weight for progress calculation (default 1, can be adjusted)
    progressMode: 'auto', // 'auto' (from subtasks) or 'manual' (set explicitly)
    manualProgress: 0, // Manual progress percentage if progressMode is 'manual'
    projectId: null, // ID of the project this task belongs to
    created: new Date().toISOString(),
    updated: new Date().toISOString(),
    tags: [],
    complexity: 5,
    aiGenerated: false,
    color: null,
    position: null,
    ...taskData
  }
}

