/**
 * Create a new task dependency
 */
export function createTaskDependency(dependencyData = {}) {
  return {
    id: generateId(),
    fromTaskId: '',
    toTaskId: '',
    type: DependencyType.FINISH_TO_START,
    lag: 0,
    ...dependencyData
  }
}

/**
 * Validate task data
 */
export function validateTask(task) {
  const errors = []

  if (!task.title || task.title.trim() === '') {
    errors.push('Task title is required')
  }

  if (!task.startDate) {
    errors.push('Start date is required')
  }

  if (!task.endDate) {
    errors.push('End date is required')
  }

  if (task.startDate && task.endDate && new Date(task.startDate) > new Date(task.endDate)) {
    errors.push('Start date must be before end date')
  }

  if (task.complexity && (task.complexity < 1 || task.complexity > 10)) {
    errors.push('Complexity must be between 1 and 10')
  }

  // Validate dependencies structure
  if (task.dependencies && Array.isArray(task.dependencies)) {
    task.dependencies.forEach((dep, index) => {
      if (typeof dep === 'object') {
        if (!dep.fromTaskId) {
          errors.push(`Dependency ${index + 1} is missing fromTaskId`)
        }
        if (dep.type && !Object.values(DependencyType).includes(dep.type)) {
          errors.push(`Dependency ${index + 1} has invalid type: ${dep.type}`)
        }
        if (dep.lag && typeof dep.lag !== 'number') {
          errors.push(`Dependency ${index + 1} lag must be a number`)
        }
      } else if (typeof dep === 'string') {
        // Legacy format - just task IDs
        if (!dep.trim()) {
          errors.push(`Dependency ${index + 1} cannot be empty`)
        }
      } else {
        errors.push(`Dependency ${index + 1} has invalid format`)
      }
    })
  }

  // Validate status
  if (task.status && !Object.values(TaskStatus).includes(task.status)) {
    errors.push('Invalid task status')
  }

  // Validate priority
  if (task.priority && !Object.values(TaskPriority).includes(task.priority)) {
    errors.push('Invalid task priority')
  }

  return {
    isValid: errors.length === 0,
    errors
  }
}

/**
 * Validate project data
 */
export function validateProject(project) {
  const errors = []

  if (!project.name || project.name.trim() === '') {
    errors.push('Project name is required')
  }

  if (
    project.startDate &&
    project.endDate &&
    new Date(project.startDate) > new Date(project.endDate)
  ) {
    errors.push('Project start date must be before end date')
  }

  if (
    project.dueDate &&
    project.startDate &&
    new Date(project.startDate) > new Date(project.dueDate)
  ) {
    errors.push('Project start date must be before due date')
  }

  if (project.gradeWeight && (project.gradeWeight < 0 || project.gradeWeight > 100)) {
    errors.push('Grade weight must be between 0 and 100')
  }

  if (
    project.completionPercentage &&
    (project.completionPercentage < 0 || project.completionPercentage > 100)
  ) {
    errors.push('Completion percentage must be between 0 and 100')
  }

  // Validate status
  if (project.status && !Object.values(ProjectStatus).includes(project.status)) {
    errors.push('Invalid project status')
  }

  // Validate priority
  if (project.priority && !Object.values(ProjectPriority).includes(project.priority)) {
    errors.push('Invalid project priority')
  }

  // Validate submission type
  if (project.submissionType && !Object.values(SubmissionType).includes(project.submissionType)) {
    errors.push('Invalid submission type')
  }

  return {
    isValid: errors.length === 0,
    errors
  }
}

/**
 * Relationship Management Utilities
 */

/**
 * Add a dependency between two tasks
 */
export function addTaskDependency(
  task,
  dependencyTaskId,
  type = DependencyType.FINISH_TO_START,
  lag = 0
) {
  if (!task.dependencies) {
    task.dependencies = []
  }

  // Check if dependency already exists
  const existingDep = task.dependencies.find(dep => dep.fromTaskId === dependencyTaskId)
  if (existingDep) {
    // Update existing dependency
    existingDep.type = type
    existingDep.lag = lag
  } else {
    // Add new dependency
    task.dependencies.push(
      createTaskDependency({
        fromTaskId: dependencyTaskId,
        toTaskId: task.id,
        type,
        lag
      })
    )
  }

  task.updated = new Date().toISOString()
  return task
}

/**
 * Remove a dependency from a task
 */
export function removeTaskDependency(task, dependencyTaskId) {
  if (!task.dependencies) {
    return task
  }

  task.dependencies = task.dependencies.filter(dep => dep.fromTaskId !== dependencyTaskId)
  task.updated = new Date().toISOString()
  return task
}

/**
 * Get all tasks that depend on a given task
 */
export function getTaskDependents(taskId, allTasks) {
  return allTasks.filter(
    task => task.dependencies && task.dependencies.some(dep => dep.fromTaskId === taskId)
  )
}

/**
 * Get all tasks that a given task depends on
 */
export function getTaskDependencies(task) {
  if (!task.dependencies) {
    return []
  }
  return task.dependencies.map(dep => dep.fromTaskId)
}

/**
 * Check for circular dependencies
 */
export function hasCircularDependency(taskId, dependencyTaskId, allTasks) {
  const visited = new Set()

  function checkCircular(currentTaskId) {
    if (visited.has(currentTaskId)) {
      return currentTaskId === taskId
    }

    visited.add(currentTaskId)

    const currentTask = allTasks.find(task => task.id === currentTaskId)
    if (!currentTask || !currentTask.dependencies) {
      return false
    }

    for (const dep of currentTask.dependencies) {
      if (checkCircular(dep.fromTaskId)) {
        return true
      }
    }

    return false
  }

  return checkCircular(dependencyTaskId)
}

/**
 * Get tasks by project ID
 */
export function getTasksByProject(projectId, allTasks) {
  return allTasks.filter(task => task.projectId === projectId)
}

/**
 * Get subtasks of a parent task
 */
export function getSubtasks(parentTaskId, allTasks) {
  return allTasks.filter(task => task.parentTask === parentTaskId)
}

/**
 * Get the root tasks (tasks without parent) for a project
 */
export function getRootTasks(projectId, allTasks) {
  return allTasks.filter(task => task.projectId === projectId && !task.parentTask)
}

// === ENHANCED HIERARCHY FUNCTIONS ===

/**
 * Calculate and update hierarchy metadata for a task
 */
export function calculateTaskHierarchy(task, allTasks) {
  const updates = {}

  if (task.parentTask) {
    const parent = allTasks.find(t => t.id === task.parentTask)
    if (parent) {
      updates.level = (parent.level || 0) + 1
      updates.hierarchyPath = [...(parent.hierarchyPath || []), parent.id]
    } else {
      updates.level = 0
      updates.hierarchyPath = []
    }
  } else {
    updates.level = 0
    updates.hierarchyPath = []
  }

  return updates
}

/**
 * Get all descendants (subtasks and their subtasks) of a task
 */
export function getTaskDescendants(taskId, allTasks) {
  const descendants = []
  const directSubtasks = getSubtasks(taskId, allTasks)

  directSubtasks.forEach(subtask => {
    descendants.push(subtask)
    descendants.push(...getTaskDescendants(subtask.id, allTasks))
  })

  return descendants
}

/**
 * Get all ancestors (parent, grandparent, etc.) of a task
 */
export function getTaskAncestors(taskId, allTasks) {
  const ancestors = []
  const task = allTasks.find(t => t.id === taskId)

  if (task && task.parentTask) {
    const parent = allTasks.find(t => t.id === task.parentTask)
    if (parent) {
      ancestors.push(parent)
      ancestors.push(...getTaskAncestors(parent.id, allTasks))
    }
  }

  return ancestors
}

/**
 * Get task hierarchy tree structure for a project
 */
export function getTaskHierarchyTree(projectId, allTasks) {
  const rootTasks = getRootTasks(projectId, allTasks)

  function buildTree(parentTasks) {
    return parentTasks.map(task => ({
      ...task,
      children: buildTree(getSubtasks(task.id, allTasks))
    }))
  }

  return buildTree(rootTasks)
}

/**
 * Get flattened task list with proper hierarchy ordering
 */
export function getFlattenedHierarchyTasks(projectId, allTasks, expandedTasks = new Set()) {
  const flattened = []
  const rootTasks = getRootTasks(projectId, allTasks).sort(
    (a, b) => (a.order || 0) - (b.order || 0)
  )

  function addTaskAndChildren(task, level = 0) {
    flattened.push({ ...task, displayLevel: level })

    if (task.isExpanded !== false && expandedTasks.has(task.id)) {
      const subtasks = getSubtasks(task.id, allTasks).sort(
        (a, b) => (a.order || 0) - (b.order || 0)
      )

      subtasks.forEach(subtask => {
        addTaskAndChildren(subtask, level + 1)
      })
    }
  }

  rootTasks.forEach(task => addTaskAndChildren(task))
  return flattened
}

/**
 * Calculate progress based on subtask completion
 */
export function calculateTaskProgress(task, allTasks) {
  if (task.progressMode === 'manual') {
    return task.manualProgress || 0
  }

  const subtasks = getSubtasks(task.id, allTasks)
  if (subtasks.length === 0) {
    // Leaf task - progress based on status
    switch (task.status) {
      case TaskStatus.COMPLETED:
        return 100
      case TaskStatus.IN_PROGRESS:
        return task.manualProgress || 50 // Default to 50% for in-progress
      default:
        return 0
    }
  }

  // Calculate weighted average of subtask progress
  const totalWeight = subtasks.reduce((sum, st) => sum + (st.progressWeight || 1), 0)
  const weightedProgress = subtasks.reduce((sum, subtask) => {
    const subtaskProgress = calculateTaskProgress(subtask, allTasks)
    const weight = subtask.progressWeight || 1
    return sum + subtaskProgress * weight
  }, 0)

  return totalWeight > 0 ? Math.round(weightedProgress / totalWeight) : 0
}

/**
 * Add a subtask to a parent task with proper hierarchy setup
 */
export function addSubtaskToParent(parentTask, subtaskData, allTasks) {
  const subtask = createTask({
    ...subtaskData,
    parentTask: parentTask.id,
    projectId: parentTask.projectId,
    order: getSubtasks(parentTask.id, allTasks).length, // Add at the end
    ...calculateTaskHierarchy({ parentTask: parentTask.id }, allTasks)
  })

  // Update parent's subtasks array
  if (!parentTask.subtasks.includes(subtask.id)) {
    parentTask.subtasks.push(subtask.id)
  }

  return subtask
}

/**
 * Remove a subtask and update parent references
 */
export function removeSubtaskFromParent(subtaskId, allTasks) {
  const subtask = allTasks.find(t => t.id === subtaskId)
  if (!subtask || !subtask.parentTask) {
    return { success: false, error: 'Subtask not found or has no parent' }
  }

  const parent = allTasks.find(t => t.id === subtask.parentTask)
  if (parent) {
    parent.subtasks = parent.subtasks.filter(id => id !== subtaskId)
  }

  // Update order of remaining subtasks
  const remainingSubtasks = getSubtasks(subtask.parentTask, allTasks).filter(
    t => t.id !== subtaskId
  )

  remainingSubtasks.forEach((task, index) => {
    task.order = index
  })

  return { success: true }
}

/**
 * Move a task to a new parent (or make it a root task)
 */
export function moveTaskToParent(taskId, newParentId, allTasks, newOrder = null) {
  const task = allTasks.find(t => t.id === taskId)
  if (!task) {
    return { success: false, error: 'Task not found' }
  }

  // Remove from old parent
  if (task.parentTask) {
    removeSubtaskFromParent(taskId, allTasks)
  }

  // Add to new parent
  if (newParentId) {
    const newParent = allTasks.find(t => t.id === newParentId)
    if (!newParent) {
      return { success: false, error: 'New parent not found' }
    }

    // Check for circular reference
    if (getTaskDescendants(taskId, allTasks).some(d => d.id === newParentId)) {
      return { success: false, error: 'Cannot move task to its own descendant' }
    }

    task.parentTask = newParentId
    task.projectId = newParent.projectId
    Object.assign(task, calculateTaskHierarchy(task, allTasks))

    if (!newParent.subtasks.includes(taskId)) {
      newParent.subtasks.push(taskId)
    }

    // Set order
    if (newOrder !== null) {
      task.order = newOrder
      // Reorder other subtasks
      const siblings = getSubtasks(newParentId, allTasks).filter(t => t.id !== taskId)
      siblings.forEach((sibling, index) => {
        sibling.order = index >= newOrder ? index + 1 : index
      })
    } else {
      task.order = getSubtasks(newParentId, allTasks).length - 1
    }
  } else {
    // Make it a root task
    task.parentTask = null
    task.level = 0
    task.hierarchyPath = []
    if (newOrder !== null) {
      task.order = newOrder
    }
  }

  // Update hierarchy for all descendants
  const descendants = getTaskDescendants(taskId, allTasks)
  descendants.forEach(descendant => {
    Object.assign(descendant, calculateTaskHierarchy(descendant, allTasks))
  })

  return { success: true }
}

/**
 * Reorder tasks within the same parent
 */
export function reorderTasks(taskIds, parentId, allTasks) {
  const tasks = taskIds.map(id => allTasks.find(t => t.id === id)).filter(Boolean)

  // Validate all tasks have the same parent
  if (!tasks.every(task => task.parentTask === parentId)) {
    return { success: false, error: 'All tasks must have the same parent' }
  }

  // Update order
  tasks.forEach((task, index) => {
    task.order = index
  })

  return { success: true }
}

/**
 * Validate hierarchy consistency for all tasks
 */
export function validateAllTaskHierarchies(allTasks, maxDepth = 5) {
  const errors = []

  allTasks.forEach(task => {
    // Check parent-child consistency
    if (task.parentTask) {
      const parent = allTasks.find(t => t.id === task.parentTask)
      if (!parent) {
        errors.push(`Task "${task.title}" has non-existent parent ${task.parentTask}`)
      } else if (!parent.subtasks.includes(task.id)) {
        errors.push(`Parent task "${parent.title}" missing subtask reference to "${task.title}"`)
      }
    }

    // Check subtask references
    if (task.subtasks && task.subtasks.length > 0) {
      task.subtasks.forEach(subtaskId => {
        const subtask = allTasks.find(t => t.id === subtaskId)
        if (!subtask) {
          errors.push(`Task "${task.title}" references non-existent subtask ${subtaskId}`)
        } else if (subtask.parentTask !== task.id) {
          errors.push(`Subtask "${subtask.title}" parent mismatch`)
        }
      })
    }

    // Check hierarchy metadata consistency
    const expectedHierarchy = calculateTaskHierarchy(task, allTasks)
    if (task.level !== expectedHierarchy.level) {
      errors.push(
        `Task "${task.title}" has incorrect level: ${task.level}, expected: ${expectedHierarchy.level}`
      )
    }

    // Check for circular references
    if (hasCircularHierarchy(task.id, allTasks)) {
      errors.push(`Circular hierarchy detected for task "${task.title}"`)
    }

    // Check depth
    if ((task.level || 0) > maxDepth) {
      errors.push(`Task "${task.title}" exceeds maximum hierarchy depth of ${maxDepth}`)
    }
  })

  return {
    isValid: errors.length === 0,
    errors
  }
}

/**
 * Check for circular hierarchy references
 */
export function hasCircularHierarchy(taskId, allTasks) {
  const visited = new Set()

  function checkCircular(currentTaskId) {
    if (visited.has(currentTaskId)) {
      return true
    }

    visited.add(currentTaskId)
    const task = allTasks.find(t => t.id === currentTaskId)

    if (task && task.parentTask) {
      return checkCircular(task.parentTask)
    }

    return false
  }

  return checkCircular(taskId)
}

/**
 * Update hierarchy metadata for all tasks in a project
 */
export function updateAllTaskHierarchies(projectId, allTasks) {
  const projectTasks = getTasksByProject(projectId, allTasks)

  projectTasks.forEach(task => {
    Object.assign(task, calculateTaskHierarchy(task, allTasks))
  })

  return projectTasks
}

// === END ENHANCED HIERARCHY FUNCTIONS ===

/**
 * Validate all relationships in a project
 */
export function validateProjectRelationships(project, tasks) {
  const errors = []
  const projectTasks = getTasksByProject(project.id, tasks)

  // Check for orphaned task references
  projectTasks.forEach(task => {
    // Check dependencies
    if (task.dependencies) {
      task.dependencies.forEach(dep => {
        const dependencyTask = tasks.find(t => t.id === dep.fromTaskId)
        if (!dependencyTask) {
          errors.push(`Task "${task.title}" has dependency on non-existent task ${dep.fromTaskId}`)
        }
      })
    }

    // Check parent task references
    if (task.parentTask) {
      const parentTask = tasks.find(t => t.id === task.parentTask)
      if (!parentTask) {
        errors.push(`Task "${task.title}" has non-existent parent task ${task.parentTask}`)
      } else if (parentTask.projectId !== task.projectId) {
        errors.push(`Task "${task.title}" and its parent are in different projects`)
      }
    }

    // Check subtask consistency
    if (task.subtasks && task.subtasks.length > 0) {
      task.subtasks.forEach(subtaskId => {
        const subtask = tasks.find(t => t.id === subtaskId)
        if (!subtask) {
          errors.push(`Task "${task.title}" references non-existent subtask ${subtaskId}`)
        } else if (subtask.parentTask !== task.id) {
          errors.push(
            `Subtask "${subtask.title}" parent reference doesn't match parent's subtask list`
          )
        }
      })
    }
  })

  // Check for circular dependencies
  projectTasks.forEach(task => {
    if (task.dependencies) {
      task.dependencies.forEach(dep => {
        if (hasCircularDependency(task.id, dep.fromTaskId, tasks)) {
          errors.push(`Circular dependency detected involving task "${task.title}"`)
        }
      })
    }
  })

  return {
    isValid: errors.length === 0,
    errors
  }
}

