/**
 * Advanced Validation Rules
 */

/**
 * Validate task workflow transitions
 */
export function validateTaskStatusTransition(currentStatus, newStatus, task = null) {
  const validTransitions = {
    [TaskStatus.TODO]: [TaskStatus.IN_PROGRESS, TaskStatus.ON_HOLD, TaskStatus.CANCELLED],
    [TaskStatus.IN_PROGRESS]: [
      TaskStatus.COMPLETED,
      TaskStatus.ON_HOLD,
      TaskStatus.TODO,
      TaskStatus.CANCELLED
    ],
    [TaskStatus.ON_HOLD]: [TaskStatus.TODO, TaskStatus.IN_PROGRESS, TaskStatus.CANCELLED],
    [TaskStatus.COMPLETED]: [TaskStatus.IN_PROGRESS], // Allow reopening completed tasks
    [TaskStatus.CANCELLED]: [TaskStatus.TODO] // Allow reactivating cancelled tasks
  }

  const allowedNext = validTransitions[currentStatus] || []
  const isValid = allowedNext.includes(newStatus)

  const errors = []
  if (!isValid) {
    errors.push(`Cannot transition from ${currentStatus} to ${newStatus}`)
  }

  // Additional business rules
  if (newStatus === TaskStatus.COMPLETED && task) {
    // Check if all subtasks are completed
    if (task.subtasks && task.subtasks.length > 0) {
      // This would require access to all tasks to check subtask status
      // Will be validated at the store level
    }
  }

  return { isValid, errors }
}

/**
 * Validate project workflow transitions
 */
export function validateProjectStatusTransition(currentStatus, newStatus) {
  const validTransitions = {
    [ProjectStatus.ACTIVE]: [
      ProjectStatus.ON_HOLD,
      ProjectStatus.COMPLETED,
      ProjectStatus.CANCELLED
    ],
    [ProjectStatus.ON_HOLD]: [ProjectStatus.ACTIVE, ProjectStatus.CANCELLED],
    [ProjectStatus.COMPLETED]: [ProjectStatus.ACTIVE], // Allow reopening
    [ProjectStatus.CANCELLED]: [ProjectStatus.ACTIVE] // Allow reactivation
  }

  const allowedNext = validTransitions[currentStatus] || []
  const isValid = allowedNext.includes(newStatus)

  return {
    isValid,
    errors: isValid ? [] : [`Cannot transition project from ${currentStatus} to ${newStatus}`]
  }
}

/**
 * Validate task hierarchy depth
 */
export function validateTaskHierarchy(task, allTasks, maxDepth = 5) {
  const errors = []

  function getDepth(taskId, visited = new Set()) {
    if (visited.has(taskId)) {
      errors.push('Circular reference detected in task hierarchy')
      return 0
    }

    visited.add(taskId)
    const currentTask = allTasks.find(t => t.id === taskId)

    if (!currentTask || !currentTask.parentTask) {
      return 0
    }

    return 1 + getDepth(currentTask.parentTask, new Set(visited))
  }

  const depth = getDepth(task.id)

  if (depth > maxDepth) {
    errors.push(`Task hierarchy depth (${depth}) exceeds maximum allowed depth (${maxDepth})`)
  }

  return {
    isValid: errors.length === 0,
    errors,
    depth
  }
}

/**
 * Validate task timeline consistency
 */
export function validateTaskTimeline(task, allTasks = []) {
  const errors = []

  if (!task.startDate || !task.endDate) {
    return { isValid: true, errors } // Skip if dates not set
  }

  const startDate = new Date(task.startDate)
  const endDate = new Date(task.endDate)

  // Basic date validation
  if (startDate >= endDate) {
    errors.push('Start date must be before end date')
  }

  // Validate against dependencies
  if (task.dependencies && task.dependencies.length > 0) {
    task.dependencies.forEach(dep => {
      const dependencyTask = allTasks.find(t => t.id === dep.fromTaskId)
      if (dependencyTask && dependencyTask.endDate) {
        const depEndDate = new Date(dependencyTask.endDate)

        switch (dep.type) {
          case DependencyType.FINISH_TO_START:
            const minStartDate = new Date(depEndDate)
            minStartDate.setDate(minStartDate.getDate() + (dep.lag || 0))
            if (startDate < minStartDate) {
              errors.push(`Task cannot start before dependency "${dependencyTask.title}" finishes`)
            }
            break

          case DependencyType.START_TO_START:
            const depStartDate = new Date(dependencyTask.startDate)
            const minStartDateSS = new Date(depStartDate)
            minStartDateSS.setDate(minStartDateSS.getDate() + (dep.lag || 0))
            if (startDate < minStartDateSS) {
              errors.push(`Task cannot start before dependency "${dependencyTask.title}" starts`)
            }
            break
        }
      }
    })
  }

  // Validate against parent task dates
  if (task.parentTask) {
    const parentTask = allTasks.find(t => t.id === task.parentTask)
    if (parentTask && parentTask.startDate && parentTask.endDate) {
      const parentStart = new Date(parentTask.startDate)
      const parentEnd = new Date(parentTask.endDate)

      if (startDate < parentStart || endDate > parentEnd) {
        errors.push('Task dates must be within parent task date range')
      }
    }
  }

  return {
    isValid: errors.length === 0,
    errors
  }
}

/**
 * Client-side Form Validation Utilities
 */

/**
 * Real-time field validation
 */
export function validateField(fieldName, value, context = {}) {
  const errors = []

  switch (fieldName) {
    case 'title':
      if (!value || value.trim().length === 0) {
        errors.push('Title is required')
      } else if (value.trim().length > 255) {
        errors.push('Title must be 255 characters or less')
      }
      break

    case 'description':
      if (value && value.length > 2000) {
        errors.push('Description must be 2000 characters or less')
      }
      break

    case 'startDate':
      if (value) {
        const date = new Date(value)
        if (isNaN(date.getTime())) {
          errors.push('Invalid start date')
        } else if (context.endDate && date >= new Date(context.endDate)) {
          errors.push('Start date must be before end date')
        }
      }
      break

    case 'endDate':
      if (value) {
        const date = new Date(value)
        if (isNaN(date.getTime())) {
          errors.push('Invalid end date')
        } else if (context.startDate && date <= new Date(context.startDate)) {
          errors.push('End date must be after start date')
        }
      }
      break

    case 'priority':
      if (value && !Object.values(TaskPriority).includes(value)) {
        errors.push('Invalid priority value')
      }
      break

    case 'status':
      if (value && !Object.values(TaskStatus).includes(value)) {
        errors.push('Invalid status value')
      }
      break

    case 'complexity':
      if (value !== null && value !== undefined) {
        const num = Number(value)
        if (isNaN(num) || num < 1 || num > 10) {
          errors.push('Complexity must be between 1 and 10')
        }
      }
      break

    case 'gradeWeight':
      if (value !== null && value !== undefined) {
        const num = Number(value)
        if (isNaN(num) || num < 0 || num > 100) {
          errors.push('Grade weight must be between 0 and 100')
        }
      }
      break
  }

  return {
    isValid: errors.length === 0,
    errors
  }
}

/**
 * Validate user actions
 */
export function validateUserAction(action, target, context = {}) {
  const errors = []

  switch (action) {
    case 'delete-task':
      if (target.subtasks && target.subtasks.length > 0) {
        errors.push(
          'Cannot delete task with subtasks. Delete subtasks first or convert them to standalone tasks.'
        )
      }

      // Check if other tasks depend on this one
      if (context.allTasks) {
        const dependents = getTaskDependents(target.id, context.allTasks)
        if (dependents.length > 0) {
          const dependentTitles = dependents.map(t => `"${t.title}"`).join(', ')
          errors.push(`Cannot delete task. The following tasks depend on it: ${dependentTitles}`)
        }
      }
      break

    case 'delete-project':
      if (context.allTasks && context.allTasks.length > 0) {
        errors.push('Cannot delete project with tasks. Delete all tasks first.')
      }
      break

    case 'change-task-status':
      if (context.currentStatus && context.newStatus) {
        const transition = validateTaskStatusTransition(
          context.currentStatus,
          context.newStatus,
          target
        )
        if (!transition.isValid) {
          errors.push(...transition.errors)
        }
      }
      break

    case 'add-dependency':
      if (context.dependencyTaskId) {
        if (target.id === context.dependencyTaskId) {
          errors.push('Task cannot depend on itself')
        }

        if (
          context.allTasks &&
          hasCircularDependency(target.id, context.dependencyTaskId, context.allTasks)
        ) {
          errors.push('Adding this dependency would create a circular reference')
        }
      }
      break
  }

  return {
    isValid: errors.length === 0,
    errors
  }
}

/**
 * Bulk validation for multiple entities
 */
export function validateProjectData(project, tasks) {
  const errors = []

  // Validate project itself
  const projectValidation = validateProject(project)
  if (!projectValidation.isValid) {
    errors.push(...projectValidation.errors.map(e => `Project: ${e}`))
  }

  // Validate that all tasks belong to this project
  const orphanedTasks = tasks.filter(task => task.projectId !== project.id)
  if (orphanedTasks.length > 0) {
    errors.push(`Found ${orphanedTasks.length} tasks that don't belong to this project`)
  }

  // Validate task relationships within the project
  const relationshipValidation = validateProjectRelationships(project, tasks)
  if (!relationshipValidation.isValid) {
    errors.push(...relationshipValidation.errors.map(e => `Relationships: ${e}`))
  }

  return {
    isValid: errors.length === 0,
    errors
  }
}

