/**
 * Project Template Constants
 */
export const ProjectTemplate = {
  BLANK: 'blank',
  ACADEMIC: 'academic',
  RESEARCH: 'research',
  SOFTWARE_DEV: 'software-dev',
  PERSONAL: 'personal',
  BUSINESS: 'business'
}

/**
 * Create a new project list entry for project management
 */
export function createProjectListItem(project) {
  const tasks = [] // Will be populated when loading tasks
  const stats = calculateProjectStats(project, tasks)

  return {
    id: project.id,
    name: project.name,
    description: project.description,
    status: project.status,
    priority: project.priority,
    color: project.color,
    created: project.created,
    updated: project.updated,
    dueDate: project.dueDate,
    completionPercentage: project.completionPercentage,
    taskCount: 0,
    lastAccessed: new Date().toISOString(),
    stats
  }
}

/**
 * Calculate project statistics
 */
export function calculateProjectStats(project, tasks = []) {
  const projectTasks = tasks.filter(task => task.projectId === project.id)

  const totalTasks = projectTasks.length
  const completedTasks = projectTasks.filter(task => task.status === TaskStatus.COMPLETED).length
  const inProgressTasks = projectTasks.filter(task => task.status === TaskStatus.IN_PROGRESS).length
  const todoTasks = projectTasks.filter(task => task.status === TaskStatus.TODO).length

  // Calculate overdue tasks
  const now = new Date()
  const overdueTasks = projectTasks.filter(task => {
    if (task.status === TaskStatus.COMPLETED) return false
    return task.endDate && new Date(task.endDate) < now
  }).length

  return {
    totalTasks,
    completedTasks,
    inProgressTasks,
    todoTasks,
    overdueTasks,
    completionPercentage: totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0,
    isOverdue:
      project.dueDate &&
      new Date(project.dueDate) < now &&
      project.status !== ProjectStatus.COMPLETED
  }
}

